typeql:
match
$m isa movie, has runtime $r;
$r > 120;
sort $r desc;
limit 5;
fetch {
  "title": $m.title,
  "runtime": $r
};

match
$m isa movie, has imdb_rating $ir;
$ir < 5.0;
$g isa genre;
in_genre (film: $m, genre: $g);
reduce $avg_rating = mean($ir) groupby $g;
sort $avg_rating asc;
limit 3;
fetch {
  "genre": $g.name,
  "avgRating": $avg_rating
};

match
$d isa person, has bio $b;
directed (director: $d);
limit 5;
fetch {
  "name": $d.name,
  "bio": $b
};

match
  $a isa person;
  acted_in (actor: $a, film: $m);
  $d isa person;
  directed (director: $d, film: $m);
select $a, $m, $d;
distinct;
reduce $directorCount = count($d) groupby $a, $m;
match
  $directorCount >= 3;
sort $directorCount desc;
limit 5;
fetch {
  "actorName": $a.name,
  "directorCount": $directorCount
};

match
$d isa person, has gender "female", has name $dn;
$m isa movie, has title $mt;
directed (director: $d, film: $m);
limit 5;
fetch {
  "MovieTitle": $mt,
  "DirectorName": $dn
};

match
$a isa person;
$rel isa acted_in (actor: $a, film: $m);
reduce $roles = count($rel) groupby $a;
sort $roles desc;
limit 3;
fetch { "actorName": $a.name, "roles": $roles };

match
$m isa movie;
rated (user: $u, film: $m);
reduce $ratingCount = count($u) groupby $m;
match
$ratingCount >= 10;
sort $ratingCount desc;
limit 3;
fetch {
  "movieTitle": $m.title,
  "ratingCount": $ratingCount
};

with fun language_count($m: movie) -> integer:
  match $m has languages $l;
  return count;

match
$m isa movie;
in_genre (film: $m, genre: $g);
let $lang_count = language_count($m);
reduce $avg_langs = mean($lang_count) groupby $g;
sort $avg_langs desc;
limit 5;
fetch { "genre": $g.name, "avgLanguages": $avg_langs };

match
$a isa person, has name $name;
$m isa movie, has title $title, has budget $budget;
$budget > 200000000;
acted_in (actor: $a, film: $m);
limit 3;
fetch {
  "ActorName": $name,
  "MovieTitle": $title,
  "Budget": $budget
};

match
$d isa person;
directed (director: $d, film: $m);
$m has imdb_rating $r;
reduce $avg = mean($r) groupby $d;
sort $avg desc;
limit 5;
fetch {
  "Director": $d.name,
  "AverageRating": $avg
};

match
$m isa movie, has title $title, has budget $budget, has revenue $revenue;
let $profit = $revenue - $budget;
sort $profit desc;
limit 3;
fetch {
  "title": $title,
  "budget": $budget,
  "revenue": $revenue,
  "profit": $profit
};

match
$m isa movie, has imdb_rating $r, has imdb_votes $v;
$r > 7.0;
sort $v asc;
limit 3;
fetch {
  "title": $m.title,
  "imdbVotes": $v
};

match
$u isa user;
$m isa movie, has year $y;
$y < 2000;
$r isa rated (user: $u, film: $m);
reduce $numRatings = count($r) groupby $u;
sort $numRatings desc;
limit 5;
fetch {
  "userName": $u.name,
  "numRatings": $numRatings
};

match
$a isa person, has born_in "France";
acted_in (actor: $a, film: $m);
$m isa movie, has year $y;
sort $y asc;
limit 3;
fetch {
  "MovieTitle": $m.title,
  "ReleaseYear": $y
};

with fun country_count($m: movie) -> integer:
  match $m has countries $c;
  return count;

match
$m isa movie;
let $ctry_count = country_count($m);
$ctry_count > 0;
sort $ctry_count desc;
limit 5;
fetch { "title": $m.title, "numCountries": $ctry_count };

match
  $m isa movie, has budget $b;
  $g isa genre;
  in_genre (film: $m, genre: $g);
  $b < 50000000;
reduce $movie_count = count($m) groupby $g;
sort $movie_count desc;
limit 3;
fetch { "genre": $g.name, "movie_count": $movie_count };

match
$m isa movie, has imdb_rating $rating;
{ $m has plot $p; $p like ".*young boy.*"; } or { $m has plot $p; $p like ".*orphan.*"; };
sort $rating desc;
limit 5;
fetch {
  "title": $m.title,
  "plot": $m.plot,
  "imdb_rating": $rating
};

match
$u isa user, has age $a;
$m isa movie;
$r isa rated (user: $u, film: $m);
$r has rating $rating;
sort $a asc;
limit 3;
fetch {
  "MovieTitle": $m.title,
  "UserName": $u.name,
  "Rating": $rating
};

match
$a isa person;
acted_in (actor: $a, film: $m);
$m has revenue $r;
reduce $total_revenue = sum($r) groupby $a;
sort $total_revenue desc;
limit 5;
fetch { "actor_name": $a.name, "total_revenue": $total_revenue };

match
$m isa movie, has runtime $r;
sort $r desc;
limit 3;
fetch {
  "title": $m.title,
  "runtime": $r
};

match
$d isa person, has born_in $bi;
$bi like ".*Nebraska.*";
directed (director: $d, film: $m);
acted_in (actor: $a, film: $m);
$a has name $name;
select $name;
distinct;
sort $name;
limit 5;
fetch {
  "name": $name
};

match
$a isa person, has born_in "USA";
acted_in (actor: $a, film: $m);
reduce $movie_count = count($m) groupby $a;
match
$movie_count >= 2;
sort $movie_count desc;
limit 5;
fetch {
  "actorName": $a.name,
  "movieCount": $movie_count
};

match
$m isa movie, has poster $poster, has released $r, has title $t;
$r > "2010-01-01";
sort $r asc;
limit 3;
fetch {
  "title": $t,
  "poster": $poster,
  "released": $r
};

match
$m isa movie;
$r isa rated (user: $u, film: $m);
reduce $numRatings = count($r) groupby $m;
sort $numRatings desc;
limit 5;
fetch {
  "title": $m.title,
  "numRatings": $numRatings
};

match
$m isa movie;
$g isa genre;
in_genre (film: $m, genre: $g);
reduce $genreCount = count($g) groupby $m;
sort $genreCount desc;
limit 3;
fetch {
  "MovieTitle": $m.title,
  "genreCount": $genreCount
};

match
$u isa user, has name "John";
$rel isa rated (user: $u, film: $m);
$rel has rating $r;
reduce $avg_rating = mean($r) groupby $m;
sort $avg_rating desc;
limit 5;
fetch {
  "title": $m.title,
  "avgRating": $avg_rating
};

match
$m isa movie, has languages $l;
$l like ".*English.*";
$l like ".*French.*";
in_genre (film: $m, genre: $g);
$g has name $n;
select $n;
distinct;
limit 3;
fetch { "name": $n };

match
$d isa person;
$m isa movie, has year $y;
directed (director: $d, film: $m);
$y >= 2000;
$y < 2010;
reduce $count = count($m) groupby $d;
sort $count desc;
limit 5;
fetch { "name": $d.name, "movieCount": $count };

with fun language_count($m: movie) -> integer:
  match $m has languages $l;
  return count;

match
$m isa movie;
let $lang_count = language_count($m);
$lang_count > 0;
sort $lang_count desc;
limit 3;
fetch { "title": $m.title, "languageCount": $lang_count };

match
$u isa user;
$m isa movie;
$r isa rated (user: $u, film: $m);
$r has timestamp $t;
sort $t asc;
limit 3;
fetch {
  "MovieTitle": $m.title,
  "ReleaseDate": $m.released
};

match
$m isa movie, has runtime 90;
$g isa genre;
in_genre (film: $m, genre: $g);
reduce $count = count($m) groupby $g;
sort $count desc;
limit 5;
fetch {
  "genre": $g.name,
  "movieCount": $count
};

match
$a isa person, has born_in $bi, has died_in $di;
$bi == $di;
acted_in (actor: $a);
select $a, $bi;
distinct;
limit 5;
fetch {
  "name": $a.name,
  "born_in": $bi
};

match
$d isa person, has bio $b, has name $n;
directed (director: $d);
let $len = len($b);
sort $len desc;
limit 3;
fetch {
  "name": $n,
  "bio": $b
};

match
$m isa movie, has tmdb_id $tid, has imdb_id $iid;
limit 3;
fetch {
  "title": $m.title,
  "tmdbId": $tid,
  "imdbId": $iid
};

match
$m isa movie;
rated (user: $u, film: $m);
$u isa user;
located_in (resident: $u, country: $c);
$c has name $cn;
select $m, $cn;
distinct;
reduce $country_count = count groupby $m;
match $country_count > 5;
$m has title $t;
sort $country_count desc;
limit 5;
fetch { "MovieTitle": $t, "NumberOfCountries": $country_count };

match
$a isa person;
acted_in (actor: $a);
directed (director: $a, film: $m);
