with fun max_imdb_rating($u: user) -> double:
    match
      rated (user: $u, film: $m);
      $m has imdb_rating $ir;
    return max($ir);
with fun min_imdb_rating($u: user) -> double:
    match
      rated (user: $u, film: $m);
      $m has imdb_rating $ir;
    return min($ir);
match
  $u isa user;
let $max_r = max_imdb_rating($u);
let $min_r = min_imdb_rating($u);
let $range = $max_r - $min_r;
sort $range desc;
limit 3;
fetch { "userId": $u.user_id, "name": $u.name, "ratingRange": $range };

