rated (user: $u, film: $m);
acted_in (actor: $a, film: $m);
select $u, $a;
distinct;
reduce $actorCount = count groupby $u;
sort $actorCount desc;
limit 3;
fetch { "userName": $u.name, "actorCount": $actorCount };

