match
$d isa person, has born_in $bi;
$m isa movie, has countries $c;
directed (director: $d, film: $m);
$bi == $c;
fetch {
  "DirectorName": $d.name,
  "MovieTitle": $m.title,
  "CountryOfBirth": $bi
};

with fun country_count($m: movie) -> integer:
  match $m has countries $c;
  return count;

match
$m isa movie;
let $ctry_count = country_count($m);
$ctry_count > 0;
sort $ctry_count desc;
limit 3;
fetch { "title": $m.title, "numCountries": $ctry_count };

match
$m isa movie, has revenue $rev;
$rev > 1000000000;
fetch {
  "title": $m.title,
  "revenue": $rev
};

match
$a isa person, has bio $b, has name $n;
$b like ".*Broadway.*";
fetch {
  "name": $n,
  "bio": $b
};

match
$u isa user;
rated (user: $u, film: $m);
in_genre (film: $m, genre: $g);
select $u, $g;
distinct;
reduce $genreCount = count($g) groupby $u;
match
$genreCount > 3;
$u has name $userName;
fetch {
  "userName": $userName,
  "genreCount": $genreCount
};

match
$m isa movie, has revenue $rev, has title $title;
$rev > 100000000;
$rel isa rated (user: $u, film: $m);
reduce $count = count($u) groupby $m, $title, $rev;
match
$count > 500;
fetch {
  "MovieTitle": $title,
  "Revenue": $rev,
  "NumberOfRatings": $count
};

with fun language_count($m: movie) -> integer:
  match $m has languages $l;
  return count;

match
$m isa movie;
let $lang_count = language_count($m);
$lang_count > 0;
sort $lang_count desc;
limit 5;
fetch { "title": $m.title, "languageCount": $lang_count };

match
$d isa person, has died $died;
$died < 2000-01-01;
$m isa movie;
directed (director: $d, film: $m);
fetch {
  "MovieTitle": $m.title,
  "DirectorName": $d.name
};

match
$a isa person, has born_in "Canada";
$m isa movie;
acted_in (actor: $a, film: $m);
fetch {
  "MovieTitle": $m.title,
  "ReleaseYear": $m.year,
  "ActorName": $a.name
};

match
$a isa person;
$m isa movie, has imdb_rating $ir;
$ir >= 9.0;
acted_in (actor: $a, film: $m);
fetch {
  "ActorName": $a.name,
  "MovieTitle": $m.title,
  "IMDbRating": $ir
};

match
$a isa person;
acted_in (actor: $a, film: $m);
directed (director: $a, film: $m2);
$m isa movie;
$m2 isa movie;
select $m;
distinct;
fetch {
  "MovieTitle": $m.title
};

match
$m isa movie, has plot $p, has title $t;
$p like ".*escape.*";
fetch {
  "title": $t,
  "plot": $p
};

match
$a isa person, has name $n;
$m isa movie, has released $r;
$r like ".*-01-01";
acted_in (actor: $a, film: $m);
select $n;
distinct;
fetch { "name": $n };

match
$m isa movie, has plot $plot;
$plot like ".*monster.*";
fetch {
  "MovieTitle": $m.title,
  "Plot": $plot
};

match
$d isa person, has born_in "USA";
$m isa movie, has imdb_rating $ir;
$ir < 5.0;
directed (director: $d, film: $m);
fetch {
  "MovieTitle": $m.title,
  "IMDbRating": $ir,
  "DirectorName": $d.name
};

match
$m isa movie;
$u isa user;
rated (user: $u, film: $m);
select $m, $u;
distinct;
reduce $userCount = count($u) groupby $m;
match
$userCount >= 5;
fetch {
  "MovieTitle": $m.title,
  "userCount": $userCount
};

match
$actor isa person;
$movie isa movie;
acted_in (actor: $actor, film: $movie);
directed (director: $actor, film: $directed_movie);
$directed_movie isa movie;
select $movie;
distinct;
fetch { "MovieTitle": $movie.title };

match
$d isa person;
$m isa movie, has languages $l;
directed (director: $d, film: $m);
not { $l like ".*English.*"; };
$d has name $n;
select $n;
distinct;
fetch { "name": $n };

with fun country_count($m: movie) -> integer:
  match $m has countries $c;
  return count;

match
$m isa movie;
let $ctry_count = country_count($m);
$ctry_count > 0;
sort $ctry_count desc;
limit 3;
fetch { "title": $m.title, "numCountries": $ctry_count };

match
$a isa person, has poster $p, has name $n;
$p like ".*smile.*";
fetch {
  "name": $n,
  "poster": $p
};

match
$d isa person;
directed (director: $d, film: $m);
$r isa rated (user: $u, film: $m);
$r has rating $rating;
$rating < 3.0;
select $d;
distinct;
fetch {
  "name": $d.name
};

match
$m isa movie, has languages $l, has title $t;
$l like ".*Japanese.*";
fetch {
  "title": $t,
  "languages": $l
};

match
$a isa person, has bio $b;
acted_in (actor: $a);
let $len = len($b);
sort $len desc;
limit 1;
fetch {
  "name": $a.name,
  "bio": $b
};

match
  $u isa user;
  $rel isa rated (user: $u, film: $m);
reduce $numRatings = count($rel) groupby $u;
match $numRatings > 100;
match $rel2 isa rated (user: $u, film: $m2);
$rel2 has rating $r2;
reduce $avgRating = mean($r2) groupby $m2;
sort $avgRating desc;
limit 10;
fetch { "MovieTitle": $m2.title, "AverageRating": $avgRating };

match
$m isa movie, has plot $plot, has title $title;
$plot like ".*hero.*";
fetch {
  "title": $title,
  "plot": $plot
};

match
$d isa person, has born $b;
directed (director: $d);
select $d, $b;
distinct;
sort $b asc;
limit 5;
fetch {
  "name": $d.name,
  "born": $b
};

match
$m isa movie;
$a isa person;
acted_in (actor: $a, film: $m);
select $m, $a;
distinct;
reduce $count = count($a) groupby $m;
match $count > 10;
$m has title $title;
fetch { "movieTitle": $title, "actorCount": $count };

match
$d isa person;
directed (director: $d, film: $m);
$m isa movie;
reduce $movie_count = count($m) groupby $d;
match
$movie_count > 5;
directed (director: $d, film: $m2);
$m2 isa movie;
fetch {
  "Director": $d.name,
  "MovieTitle": $m2.title
};

match
$m isa movie, has imdb_votes $v;
sort $v asc;
limit 3;
fetch {
  "title": $m.title,
  "imdb_votes": $v
};

match
$director isa person;
directed (director: $director, film: $movie);
acted_in (actor: $director, film: $actedMovie);
select $movie;
distinct;
fetch {
  "MovieTitle": $movie.title
};

match
$a isa person, has name $an, has born_in $country;
$d isa person, has name $dn, has born_in $country;
$m isa movie;
acted_in (actor: $a, film: $m);
directed (director: $d, film: $m);
select $an, $dn, $country;
distinct;
fetch {
  "ActorName": $an,
  "DirectorName": $dn,
  "Country": $country
};

match
$m isa movie, has year $y, has revenue $r;
$y >= 1990;
$y < 2000;
sort $r desc;
limit 5;
fetch {
  "title": $m.title,
  "revenue": $r
};
